from pathlib import Path
import base64, gzip

root = Path('src/Cardcha')
files = {
    'UI/CardRenderer.cs': '',
    'UI/CardchaBinderMenuV2.cs': '',
    'UI/CombatHudRenderer.cs': '' ,
    'UI/MimiScrapShopMenu.cs': '',
    'Services/MimiMysteryTownService.cs': '',
    'Services/CardchaStoryService.cs': '',
    'Patches/MachineProtectionPatch.cs': '',
    'ModEntry.cs': '',
    'i18n/vi.json': '',
    'i18n/default.json': '',
    'Cardcha.csproj': '',
    'manifest.json': '',
}

for rel, payload in files.items():
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

print('alpha.6: binder hover filters, readable cards, MiMi reveal/wander, shop quantities/colors, protected machines')
